import inspect
from functools import partial, wraps
import asyncio

async def iscoroutinefunction(func):
    # This is a simplified version of the one used in fastapi
    return inspect.iscoroutinefunction(func)

def is_coroutine_callable_fastapi(call):
    # Current FastAPI implementation
    def _unwrapped_call(c):
        if c is None:
            return None
        unwrapped = inspect.unwrap(c)
        if isinstance(unwrapped, partial):
            unwrapped = unwrapped.func
        return unwrapped

    unwrapped = _unwrapped_call(call)
    if inspect.isroutine(unwrapped):
        return inspect.iscoroutinefunction(unwrapped)
    if inspect.isclass(unwrapped):
        return False
    dunder_call = getattr(unwrapped, "__call__", None)
    return inspect.iscoroutinefunction(dunder_call)

# Test cases
async def async_func():
    pass

def sync_func():
    pass

def sync_wrapper(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

async def async_wrapper(func):
    @wraps(func)
    async def wrapper(*args, **kwargs):
        return await func(*args, **kwargs)
    return wrapper

# 1. Simple async func
print(f"Async func: {is_coroutine_callable_fastapi(async_func)}") # Expected: True

# 2. Simple sync func
print(f"Sync func: {is_coroutine_callable_fastapi(sync_func)}") # Expected: False

# 3. Sync wrapper around async func
wrapped_async = sync_wrapper(async_func)
print(f"Sync wrapper around async func: {is_coroutine_callable_fastapi(wrapped_async)}") # Expected: True

# 4. Async wrapper around sync func
# Note: async_wrapper is async, so we need to await it to get the wrapper
async def get_async_wrapped_sync():
    return await async_wrapper(sync_func)

# Since async_wrapper is an async function, we can't just call it.
# But in FastAPI, the decorator would be:
def async_decorator(func):
    async def wrapper(*args, **kwargs):
        return await func(*args, **kwargs)
    return wrapper

wrapped_sync_by_async = async_decorator(sync_func)
print(f"Async wrapper around sync func: {is_coroutine_callable_fastapi(wrapped_sync_by_async)}") # Expected: True

# 5. Partial of async func
partial_async = partial(async_func)
print(f"Partial of async func: {is_coroutine_callable_fastapi(partial_async)}") # Expected: True

# 6. Partial of sync wrapper around async func
partial_wrapped_async = partial(sync_wrapper(async_func))
print(f"Partial of sync wrapper around async func: {is_coroutine_callable_fastapi(partial_wrapped_async)}") # Expected: True

# 7. Sync wrapper around partial of async func
def sync_wrapper_2(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

wrapped_partial_async = sync_wrapper_2(partial(async_func))
print(f"Sync wrapper around partial of async func: {is_coroutine_callable_fastapi(wrapped_partial_async)}") # Expected: True

# 8. Partial of sync wrapper around partial of async func
partial_wrapped_partial_async = partial(sync_wrapper_2(partial(async_func)))
print(f"Partial of sync wrapper around partial of async func: {is_coroutine_callable_fastapi(partial_wrapped_partial_async)}") # Expected: True

