from typing import Annotated, Any
from fastapi import FastAPI, Query
from pydantic import BeforeValidator, WithJsonSchema
import pytest

app = FastAPI()

FilterableStr = Annotated[
    str | dict,
    BeforeValidator(lambda x: x),
    WithJsonSchema({"type": "string"}, mode="serialization"),
]

@app.get("/hello")
async def get_hello(data: FilterableStr | None = Query(default=None)) -> Any:
    return data

def test_invalid_query_param_error_message():
    try:
        # This should trigger the AssertionError during app initialization
        # Since FastAPI initializes routes on creation, we just need to create the app
        # But the app is already created above. Let's wrap it in a function.

        def create_app():
            app = FastAPI()
            @app.get("/hello")
            async def get_hello(data: FilterableStr | None = Query(default=None)) -> Any:
                return data
            return app

        create_app()
    except AssertionError as e:
        print(f"Caught expected AssertionError: {e}")
        assert str(e) == "Query param 'data' must be of one of the supported types"
    except Exception as e:
        pytest.fail(f"Caught unexpected exception: {type(e).__name__}: {e}")
    else:
        pytest.fail("AssertionError not raised")

if __name__ == "__main__":
    try:
        test_invalid_query_param_error_message()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        exit(1)

